// token → icon key (synonyms / suffixed variants the scan emits)
const ALIASES: Record<string, string> = {
  typescript: 'typescript', ts: 'typescript',
  javascript: 'javascript',
  rust: 'rust',
  react: 'react',
  node: 'node', nodejs: 'node', nodedotjs: 'node',
  tauri: 'tauri',
  github: 'github',
  sqlite: 'sqlite',
  postgres: 'postgresql', postgresql: 'postgresql',
  mongo: 'mongodb', mongodb: 'mongodb',
  redis: 'redis',
  tailwind: 'tailwind', tailwindcss: 'tailwind',
  vue: 'vue',
  astro: 'astro',
  next: 'next', nextjs: 'next',
  stripe: 'stripe',
  openai: 'openai',
  claude: 'claude',
  anthropic: 'anthropic',
  supabase: 'supabase',
  clerk: 'clerk',
  twilio: 'twilio',
  sentry: 'sentry',
  posthog: 'posthog',
  vercel: 'vercel',
  // database / data platforms
  mysql: 'mysql',
  mariadb: 'mariadb',
  prisma: 'prisma',
  firebase: 'firebase', firestore: 'firebase',
  neo4j: 'neo4j',
  clickhouse: 'clickhouse',
  cockroach: 'cockroachdb', cockroachdb: 'cockroachdb',
  snowflake: 'snowflake',
  elastic: 'elasticsearch', elasticsearch: 'elasticsearch', opensearch: 'elasticsearch',
  cassandra: 'cassandra',
  duckdb: 'duckdb',
  planetscale: 'planetscale',
  drizzle: 'drizzle',
  turso: 'turso', libsql: 'turso',
  influx: 'influxdb', influxdb: 'influxdb',
};

// brand-suffix noise dropped from the residual label (keeps counts like "20 tables")
const STOP = new Set(['js', 'css', 'dotjs', 'db', 'sql', 'io']);

/** Match a chip label to an official icon. Returns the icon + any residual text
 *  (e.g. "SQLite · 20 tables" → SQLite icon + "20 tables"). Null when no match. */
export function resolveTechIcon(label: string): { icon: BrandIcon; residual: string } | null {
  const tokens = label.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  const idx = tokens.findIndex((t) => ALIASES[t]);
  if (idx === -1) return null;
  const matched = tokens[idx]!;
  // Residual from WHITESPACE-split words (not the alias tokenizer) so version
  // dots survive — "Next.js 16.2" → "16.2", never "16 2". A word drops when it
  // carries the matched brand or reduces to brand-suffix noise.
  const residual = label
    .split(/\s+/)
    .filter((w) => {
      const wl = w.toLowerCase();
      if (wl.includes(matched)) return false;
      const bare = wl.replace(/[^a-z0-9.]+/g, '');
      return bare !== '' && !STOP.has(bare);
    })
    // trim wrapping punctuation ("(drizzle)" → "drizzle") but keep inner dots
    .map((w) => w.replace(/^[^\w.]+|[^\w.]+$/g, ''))
    .join(' ');
  return { icon: ICONS[ALIASES[matched]!]!, residual };
}

function TechGlyph({ icon, size = 14 }: { icon: BrandIcon; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={icon.color ?? 'currentColor'} aria-hidden className="flex-shrink-0">
      <path d={icon.path} />
    </svg>
  );
}

/**
 * Render a stack/tooling value as its official icon (with the name as a tooltip
 * and any residual detail beside it), falling back to a text chip when no brand
 * icon matches. This is what "cut text, more visual" looks like in the rows.
 */
export function TechBadge({ label }: { label: string }) {
  const match = resolveTechIcon(label);
  if (!match) return <Chip label={label} tone="accent" />;
  return (
    <Tooltip content={label}>
      <span className="inline-flex items-center gap-1 rounded-input bg-secondary/40 border border-primary/8 px-1.5 py-0.5 cursor-default">
        <TechGlyph icon={match.icon} />
        {match.residual && <span className="typo-caption text-foreground/70">{match.residual}</span>}
      </span>
    </Tooltip>
  );
}
